// === Tab: mySketch ===
const PARTICLE_COUNT = 1;
const CIRCLE_POINTS = 20;
const FRICTION = 0.97;
const R = 150;
const USER_INPUT_STRENGTH = 0.022;

const V = Math.PI * R*2;

let id = 1;

const SQRT_PARTICLE_COUNT = Math.sqrt(PARTICLE_COUNT);
const particles = [];
const w = 800;
const h = 600;

const pointsAttached = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);

	fill(255, 255, 255, 255);
	stroke(200, 240, 240, 120);
	strokeWeight(3.5);
	noStroke();

	for (let i = 0; i < CIRCLE_POINTS; i++) {
		const step = 360 / CIRCLE_POINTS * Math.PI/180;
		particles.push(createParticle({
			x: cos(step * i) * R + w/2,
			y: sin(step * i) * R + h/2,
			origX: w/2,
			origY: h/2,
			radius: 10,
			mass: 2400
		}));
	}

	for (let i = 0; i < CIRCLE_POINTS; i++) {
		bindParticles(particles[i], particles[(i + 1) % CIRCLE_POINTS], 1, 2);
		bindParticles(particles[i], particles[Math.abs((i - 1) % CIRCLE_POINTS)], 2, 1);
	}

	for (let i = 0; i < CIRCLE_POINTS / 2; i++) {
		bindParticles(particles[i], particles[Math.floor(CIRCLE_POINTS / 2) + i], 1, 0);
		bindParticles(particles[i], particles[(Math.floor(CIRCLE_POINTS / 2) + i - 1) % CIRCLE_POINTS], 1, 0);
		bindParticles(particles[i], particles[(Math.floor(CIRCLE_POINTS / 2) + i + 1) % CIRCLE_POINTS], 1, 0);
	}

	particles.push(createParticle({
		x: w/2,
		y: h/2,
		origX: w/2,
		origY: h/2,
		radius: 1,
		mass: 9000
	}));

	for (let i = 0; i < CIRCLE_POINTS; i++) {
		bindParticles(particles[CIRCLE_POINTS], particles[i], 1, 0);
	}

	// bind particles
	//shapeFromParticles(particles);
}

function draw() {
	background(255, 170);
	particles.map(clearForces);
	particles.map(applyForces);
	particles.map(updateParticle);
	particles.map(applyScreenConstraints);
	particles.map(drawBonds);
	particles.map(drawParticle);
	beginShape();
	//particles.sort((p1, p2) => p1.id - p2.id).slice(0, CIRCLE_POINTS).forEach(p => vertex(p.x, p.y));
	endShape();
	fill(0, 150);

	stroke(0, 120);
	strokeWeight(3.5);
	line(0, h, w, h);

	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && pointsAttached.length) {
		line((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), pointsAttached[0].x, pointsAttached[0].y);
	}

	//noStroke();
}

function clearForces(p) {
	p.jx = 0;
	p.jy = 0;

	p.ax *= 0;
	p.ay *= 0;

	/*
	if (Math.abs(p.ax) < 0.1) {
		p.ax = 0;
	}

	if (Math.abs(p.ay) < 0.1) {
		p.ay = 0;
	}

	if (Math.abs(p.vx) < 0.5) {
		p.vx = 0;
	}

	if (Math.abs(p.vy) < 0.5) {
		p.vy = 0;
	}
	*/
}

function drawParticle(particle) {
	//text(particle.id, particle.x, particle.y);
	//circle(particle.x, particle.y, particle.radius);
}

function findClosestParticlesTo(x, y, particles) {
	return particles.sort((p1, p2) => {
		let dx = x - p1.x;
		let dy = y - p1.y;
		const distSq1 = dx*dx + dy*dy;

		dx = x - p2.x;
		dy = y - p2.y;

		const distSq2 = dx*dx + dy*dy;

		return distSq1 - distSq2;
	});
}

function applyScreenConstraints(p) {
	if (p.x - p.radius <= 0) {
		p.jx = 0.001;
		p.vx *= -.92;
		p.x = p.x + p.radius + 1;
	}

	if (p.x + p.radius >= w) {
		p.jx = -0.001;
		p.vx *= -.92;
		p.x = p.x - p.radius - 1;
	}

	if (p.y - p.radius <= 0) {
		p.jy = 0.001;
		p.vy *= -.98;
		p.y = p.radius;
	}
	if (p.y + p.radius >= h) {
		p.jy = -.001;
		p.vy *= -.98;
		p.y = p.y - 1;
	}
}

function updateParticle(p) {	
	// Euler integration
	p.jx *= 0.01;
	p.jy *= 0.01;

	p.ax += p.jx;
	p.ay += p.jy + 1 * 0.07;

	p.vx += p.ax;
	p.vy += p.ay;

	const maxVel = 800;

	p.vx *= FRICTION;
	p.vy *= FRICTION;

	if (Math.abs(p.vx) > maxVel) {
		p.vx = Math.sign(p.vx) * maxVel;
	}

	if (Math.abs(p.vy) > maxVel) {
		p.vy = Math.sign(p.vy) * maxVel;
	}

	p.x += p.vx;
	p.y += p.vy;

	p.initialX = p.x;
	p.initialY = p.y;
}

function applyForces(p) {
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		pointsAttached.length = 0;
		pointsAttached.push.apply(
			pointsAttached,
			findClosestParticlesTo((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), particles).slice(0, 2)
		);

		pointsAttached.forEach((anchor, i) => {
			const dmx = anchor.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
			const dmy = anchor.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
			const dm = Math.sqrt(dmx*dmx + dmy*dmy);

			const mouseForceX = -dmx * USER_INPUT_STRENGTH * 1/(i+1);
			const mouseForceY = -dmy * USER_INPUT_STRENGTH * 1/(i+1);

			p.jx += mouseForceX;
			p.jy += mouseForceY;		
		});

	} else {
		pointsAttached.length = 0;
	}


		// pV = nRT
		// p = m/V * RT

	// update force according to bonds
	p.bonds.map(({ particle: p2, strength: springStrength, length: springLength }) => {
		const distX = (p2.x - p.x);
		const distY = (p2.y - p.y);
		const dist = Math.sqrt(distX*distX + distY*distY);

		let forceX = -distX * springStrength;
		let forceY = -distY * springStrength;

		if (dist >= springLength) {
			forceX *= -1;
			forceY *= -1;
		}

		//F = ma => a = F/m
		let ax = forceX / p.mass;
		let ay = (forceY) / p.mass;

		p.ax += ax;
		p.ay += ay;

		p2.ax -= ax;
		p2.ay -= ay;
	});
}

function drawBonds(p) {
	p.bonds.filter(bond => bond.visible).map(({ particle: p2 }) => {
		line(p.x, p.y,
				 p2.x, p2.y);
	});
}

function shapeFromParticles(particles) {
	const cols = SQRT_PARTICLE_COUNT;

	for (let y = 0; y < cols - 2; y++) {
		bindParticles(particles[cols - 1 + y * cols], particles[cols - 1 + (y + 1) * cols]);
	}

	particles.map((p, i, arr) => {
		const x = i % cols;
		const y = Math.floor(i / cols);

		if (x > 0) {
			bindParticles(p, arr[i - 1]);
		}

		if (x < cols - 1) {
			bindParticles(p, arr[i + 1]);
		}


		if (y < cols - 1) {
			bindParticles(p, arr[i + cols]);
		}

		if (y > 0) {
			bindParticles(p, arr[i - cols]);
		}

		if (x > 0 && y > 0) {
			bindParticles(p, arr[i - cols - 1]);
		}

		if (x > 0 && y < cols - 1) {
			bindParticles(p, arr[i + cols - 1]);
		}

		if (x < cols - 1 && y < cols - 1) {
			bindParticles(p, arr[i + cols + 1]);
		}

		if (x < cols - 1 && y > 0) {
			bindParticles(p, arr[i - cols + 1]);
		}
	});
}

function bindParticles(p1, p2, strength, visible = true) {
	var dx = p2.x - p1.x;
	var dy = p2.y - p1.y;

	if (!p1.bonds.includes(p2)) {
		var dist = Math.sqrt(dx*dx + dy*dy);
		p1.bonds.push({ particle: p2, length: Math.sqrt(dx*dx + dy*dy) * 1, visible, strength: strength || 1-1/dist});
	}7

	if (!p2.bonds.includes(p1)) {
		p2.bonds.push({ particle: p1, length: Math.sqrt(dx*dx + dy*dy) * 1, visible, strength: strength || 1-1/dist });
	}
}

function createParticle({ x, y, vx = 0, vy = 0, ax = 0, ay = 0, jx = 0, jy = 0, radius = 1, mass = 1, bonds = [] }) {
	return {
		id: id++,
		x, y, vx, vy, ax, ay, jx, jy, radius, mass, bonds,
		initialX: x, initialY: y
	};
}

